private val routes = new AtomicReference(Map.empty[String, Int])

def lookup(k: String): Option[Int] = routes.get().get(k)   // lock-free read

def add(k: String, v: Int): Unit =
  routes.updateAndGet { current =>                          // CAS retry loop
    current + (k -> v)                                      // new immutable Map
  }
